<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">Vue 3 · hel 宿主</p>
      <h1 class="demo-page__title">{{ APP_META.name }} 简介</h1>
      <p class="demo-page__lead">
        Vue 3 + Vite 5 的 hel 宿主（消费方）示例：入口处用
        <code>bindVueRuntime</code> 注入宿主 Vue 运行时，再用
        <code>preFetchLib</code> 预加载远程组件 <code>comps-vue3</code>。
        顶部导航栏用于切换示例，示例页右上角的「全屏」按钮只把组件预览区放大到全屏，
        简介与说明文字不会进入全屏。
      </p>
    </header>

    <table class="demo-table">
      <tbody>
        <tr>
          <th>npm 包名</th>
          <td><code>@melt-js/demo-vue3</code></td>
        </tr>
        <tr>
          <th>unpkg 入口</th>
          <td>
            <a :href="APP_META.unpkgEntry" target="_blank" rel="noopener">{{ APP_META.unpkgEntry }}</a>
          </td>
        </tr>
        <tr>
          <th>本地端口</th>
          <td>{{ APP_META.port }}</td>
        </tr>
        <tr>
          <th>远程组件</th>
          <td>
            <div><code>{{ REMOTE_LIB_NAME }}</code></div>
            <div>开发：<code>{{ LOCAL_HOST }}</code></div>
            <div>生产：<code>{{ UNPKG_HOST }}</code></div>
          </td>
        </tr>
        <tr>
          <th>运行时共享</th>
          <td><code>bindVueRuntime({ Vue })</code>，远程组件 external 的 vue 复用宿主这一份</td>
        </tr>
        <tr>
          <th>路由模式</th>
          <td>
            hash（<code>#/remote</code>），保证从 unpkg 的 <code>dist/index.html</code>
            直接打开也能切换示例
          </td>
        </tr>
      </tbody>
    </table>

    <section>
      <h2 class="demo-page__section-title">示例导航</h2>
      <div class="demo-grid">
        <router-link
          v-for="item in examples"
          :key="item.path"
          :to="item.path"
          class="demo-card demo-card--link"
        >
          <h3 class="demo-card__title">{{ item.meta?.title }}</h3>
          <p class="demo-card__text">{{ item.meta?.description }}</p>
          <span class="demo-card__action">进入示例 →</span>
        </router-link>
      </div>
    </section>

    <p class="demo-note">
      本地开发先执行 <code>pnpm comps-vue3:dev</code>（20020），再执行
      <code>pnpm demo-vue3:dev</code> 打开 http://localhost:30020；远端地址可用
      <code>VITE_REMOTE_HOST</code> 覆盖。
    </p>
  </div>
</template>

<script setup lang="ts">
import { APP_META } from '../configs/app'
import { LOCAL_HOST, REMOTE_LIB_NAME, UNPKG_HOST } from '../configs/remote'
import { demoRoutes } from '../router'

// 简介页也列出其余示例，方便直接跳转
const examples = demoRoutes.filter((item) => item.name && item.name !== 'overview')
</script>
